define("mod_questionnaire/chart",[],(function(){var drawOne=function(spec){if(typeof window.RGraph==="undefined"||typeof window.RGraph[spec.type]!=="function"){return}var canvas=document.getElementById(spec.canvasId);if(!canvas){return}var ctorArgs=[spec.canvasId].concat(spec.args||[]);var chart=new(Function.prototype.bind.apply(window.RGraph[spec.type],[null].concat(ctorArgs)))();(spec.sets||[]).forEach((function(pair){chart.Set(pair[0],pair[1])}));chart.Draw()};return{render:function(spec){if(!spec||!Array.isArray(spec.charts)){return}spec.charts.forEach(drawOne)}}}));
